package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/levitskyyy/KremenMC/internal/reftest"
	"github.com/levitskyyy/KremenMC/tools/refbench/refgen"
	"github.com/levitskyyy/KremenMC/tools/refbench/refserver"
)

// cmdExport copies a reference overworld's region files into a kremenmc world
// directory (<out>/region, the layout internal/server opens) and writes
// kremenmc-level.json with the seed and vanilla spawn, so the kremenmc server can be
// run on terrain pre-generated by the official server.
func cmdExport(_ context.Context, args []string) error {
	fs := newFlags("export")
	seed := fs.Int64("seed", 0, "world seed")
	structures := fs.Bool("structures", true, "reference generated with structures")
	out := fs.String("out", "", "kremenmc world directory to create (e.g. server/world-ref)")
	if err := fs.Parse(args); err != nil {
		return err
	}
	if *out == "" {
		return errors.New("export: -out required")
	}
	ref, err := reftest.Open()
	if err != nil {
		return err
	}
	dir := refgen.WorldDir(ref, *seed, "overworld", *structures)
	m, err := refgen.LoadManifest(dir)
	if err != nil {
		return fmt.Errorf("export: %w (run refbench gen first)", err)
	}
	src := filepath.Join(refserver.DimensionDir(filepath.Join(dir, m.World), m.Dimension), "region")
	if _, err := os.Stat(filepath.Join(*out, "region")); err == nil {
		return fmt.Errorf("export: %s already has a region directory", *out)
	}
	if err := os.MkdirAll(filepath.Join(*out, "region"), 0o755); err != nil {
		return err
	}
	ents, err := os.ReadDir(src)
	if err != nil {
		return err
	}
	n := 0
	for _, e := range ents {
		if !strings.HasSuffix(e.Name(), ".mca") {
			continue
		}
		if err := copyFile(filepath.Join(src, e.Name()), filepath.Join(*out, "region", e.Name())); err != nil {
			return err
		}
		n++
	}
	lvl := map[string]any{"seed": *seed}
	if m.Spawn != nil {
		lvl["spawn"] = []float64{float64(m.Spawn.X) + 0.5, float64(m.Spawn.Y), float64(m.Spawn.Z) + 0.5}
		lvl["spawnYaw"] = m.Spawn.Yaw
		lvl["hasSpawn"] = true
	}
	b, _ := json.MarshalIndent(lvl, "", "  ")
	if err := os.WriteFile(filepath.Join(*out, "kremenmc-level.json"), b, 0o644); err != nil {
		return err
	}
	fmt.Printf("exported %d region files of seed %d to %s (only full chunks are used; proto-chunks get regenerated by kremenmc)\n", n, *seed, *out)
	return nil
}

func copyFile(src, dst string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()
	o, err := os.Create(dst)
	if err != nil {
		return err
	}
	if _, err := io.Copy(o, in); err != nil {
		o.Close()
		return err
	}
	return o.Close()
}
